import React, { useRef, useState, useMemo, useEffect, useCallback } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, TransformControls, Html, GizmoHelper, GizmoViewport } from '@react-three/drei';
import * as THREE from 'three';
import { OrbitControls as OrbitControlsImpl } from 'three-stdlib';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, ShapeType } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DIMENSION_COLOR, DEFAULT_HEIGHT } from '../constants';

// --- Constants ---
const SNAP_THRESHOLD = 0.3; // Meters (Adsorption radius)
const ALIGN_THRESHOLD = 0.25; // Meters (Object alignment radius)
const EPSILON = 1e-5; // Floating point tolerance

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'face' | 'align';

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string; // ID of the object we snapped to
    snapEdge?: [THREE.Vector3, THREE.Vector3]; // The start/end of the edge we snapped to (for highlighting)
    guides?: THREE.Vector3[][];
}

type PushPullMode = 'top' | 'side' | 'none';

interface PushPullState {
    mode: PushPullMode;
    hoveredShapeId: string | null;
    hoveredEdgeIndex: number;
    dragStartPoint: THREE.Vector3 | null;
    originalHeight: number;
    originalPoints: IPoint[];
    normal: THREE.Vector3;
    dragHeight?: number; // Current dynamic height during drag
}

interface ShapeRendererProps {
    shape: IShape;
    isSelected: boolean;
    onSelect: (e: ThreeEvent<MouseEvent>) => void;
    pushPullState: PushPullState;
    pushPullHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: () => void;
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => void;
    };
    drawingHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: (e: ThreeEvent<PointerEvent>) => void;
        handleClick: (e: ThreeEvent<MouseEvent>) => void;
    };
}

// --- Geometry Helpers ---
// (Keep existing geometry helpers identical)
const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;
  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) shape.lineTo(points[i].x, -points[i].z);
    }
  }
  shape.closePath();
  return shape;
};

const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

const createArcPoints = (radius: number, segments = 16): IPoint[] => {
  const points: IPoint[] = [];
  points.push({ x: 0, y: 0, z: 0 });
  for (let i = 0; i <= segments; i++) {
    const theta = (i / segments) * (Math.PI / 2); 
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push({ x: 0, y: 0, z: 0 });
  return points;
};

const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    const sX = shape.scale[0];
    const sZ = shape.scale[2];
    const rot = shape.rotation;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);
    const xScaled = localP.x * sX;
    const zScaled = localP.z * sZ;
    const xRot = xScaled * cos - zScaled * sin;
    const zRot = xScaled * sin + zScaled * cos;
    return new THREE.Vector3(xRot + shape.position[0], shape.position[1], zRot + shape.position[2]);
};

const inverseTransformPoint = (worldP: THREE.Vector3, shape: IShape): IPoint => {
    const relX = worldP.x - shape.position[0];
    const relZ = worldP.z - shape.position[2];
    const rot = -shape.rotation;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);
    const xRot = relX * cos - relZ * sin;
    const zRot = relX * sin + relZ * cos;
    return { x: xRot / shape.scale[0], y: 0, z: zRot / shape.scale[2] };
};

const closestPointOnSegment = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3): THREE.Vector3 => {
  const vwx = w.x - v.x;
  const vwy = w.y - v.y;
  const vwz = w.z - v.z;
  const vpx = p.x - v.x;
  const vpy = p.y - v.y;
  const vpz = p.z - v.z;
  const dot = vpx * vwx + vpy * vwy + vpz * vwz;
  const l2 = vwx * vwx + vwy * vwy + vwz * vwz;
  if (l2 === 0) return v;
  let t = dot / l2;
  t = Math.max(0, Math.min(1, t));
  return new THREE.Vector3(v.x + t * vwx, v.y + t * vwy, v.z + t * vwz);
};

const distToSegmentSquared = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3) => {
    const l2 = v.distanceToSquared(w);
    if (l2 === 0) return p.distanceToSquared(v);
    let t = ((p.x - v.x) * (w.x - v.x) + (p.z - v.z) * (w.z - v.z)) / l2;
    t = Math.max(0, Math.min(1, t));
    return (p.x - (v.x + t * (w.x - v.x)))**2 + (p.z - (v.z + t * (w.z - v.z)))**2;
};

const getLineIntersection = (p1: IPoint, p2: IPoint, p3: IPoint, p4: IPoint): IPoint | null => {
    const d = (p2.x - p1.x) * (p4.z - p3.z) - (p2.z - p1.z) * (p4.x - p3.x);
    if (Math.abs(d) < EPSILON) return null;
    const u = ((p3.x - p1.x) * (p4.z - p3.z) - (p3.z - p1.z) * (p4.x - p3.x)) / d;
    const v = ((p3.x - p1.x) * (p2.z - p1.z) - (p3.z - p1.z) * (p2.x - p1.x)) / d;
    if (u >= 0 && u <= 1 && v >= 0 && v <= 1) {
        return { x: p1.x + u * (p2.x - p1.x), y: 0, z: p1.z + u * (p2.z - p1.z) };
    }
    return null;
};

const splitPolygonByLine = (polyPoints: IPoint[], cutStart: IPoint, cutEnd: IPoint): [IPoint[], IPoint[]] | null => {
    const intersections: { point: IPoint; edgeIndex: number; dist: number }[] = [];
    for (let i = 0; i < polyPoints.length; i++) {
        const p1 = polyPoints[i];
        const p2 = polyPoints[(i + 1) % polyPoints.length];
        const hit = getLineIntersection(p1, p2, cutStart, cutEnd);
        if (hit) {
            const isP1 = Math.abs(hit.x - p1.x) < 0.001 && Math.abs(hit.z - p1.z) < 0.001;
            const isP2 = Math.abs(hit.x - p2.x) < 0.001 && Math.abs(hit.z - p2.z) < 0.001;
            if (!isP1 && !isP2) {
                const dist = Math.sqrt((hit.x - cutStart.x)**2 + (hit.z - cutStart.z)**2);
                intersections.push({ point: hit, edgeIndex: i, dist });
            }
        }
    }
    if (intersections.length !== 2) return null;
    intersections.sort((a, b) => a.dist - b.dist);
    const [int1, int2] = intersections;
    const fullCycle: IPoint[] = [];
    for (let i = 0; i < polyPoints.length; i++) {
        fullCycle.push(polyPoints[i]);
        if (i === int1.edgeIndex) fullCycle.push(int1.point);
        if (i === int2.edgeIndex) fullCycle.push(int2.point);
    }
    const idx1 = fullCycle.indexOf(int1.point);
    const idx2 = fullCycle.indexOf(int2.point);
    if (idx1 === -1 || idx2 === -1) return null;
    const minIdx = Math.min(idx1, idx2);
    const maxIdx = Math.max(idx1, idx2);
    const polyA = fullCycle.slice(minIdx, maxIdx + 1);
    const polyB = [...fullCycle.slice(maxIdx), ...fullCycle.slice(0, minIdx + 1)];
    return [polyA, polyB];
};

// --- Geometry Snapping Logic (Optimized for usage outside render loop) ---
const getGeometrySnap = (
    cursorPos: THREE.Vector3, 
    shapes: IShape[], 
    activePoints: IPoint[] = [],
    threshold: number,
    intersectedObject?: THREE.Intersection
): SnapResult => {
    let bestSnap: SnapResult = {
        position: new THREE.Vector3(
            Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID,
            cursorPos.y, 
            Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID
        ),
        type: 'grid',
        distance: Infinity
    };

    if (activePoints && activePoints.length > 0) {
        const first = activePoints[0];
        const pt = new THREE.Vector3(first.x, first.y, first.z);
        const dist = pt.distanceTo(cursorPos);
        if (dist < threshold) {
            return { position: pt, type: 'vertex', distance: dist };
        }
    }

    // Optimization: Check bounding box first or limit to nearby shapes?
    // For now, simple loop is fine for < 100 shapes.
    for (const shape of shapes) {
        if (shape.type === 'dimension') continue;
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;

        for (let i = 0; i < shape.points.length; i++) {
            const worldPt = transformPoint(shape.points[i], shape);
            let dist = worldPt.distanceTo(cursorPos);
            if (dist < threshold && dist < bestSnap.distance) {
                bestSnap = { position: worldPt, type: 'vertex', distance: dist, snapObjectId: shape.id };
            }
            if (hasHeight) {
                const worldPtTop = worldPt.clone().setY(worldPt.y + currentH);
                dist = worldPtTop.distanceTo(cursorPos);
                if (dist < threshold && dist < bestSnap.distance) {
                    bestSnap = { position: worldPtTop, type: 'vertex', distance: dist, snapObjectId: shape.id };
                }
            }
        }
    }
    if (bestSnap.type === 'vertex') return bestSnap;

    // Edge snapping
    let bestEdgeSnap: SnapResult | null = null;
    let minEdgeDist = threshold;
    for (const shape of shapes) {
        if (shape.type === 'dimension') continue;
        const pts = shape.points;
        const len = pts.length;
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;
        for (let i = 0; i < len; i++) {
             const p1 = transformPoint(pts[i], shape);
             const p2 = transformPoint(pts[(i + 1) % len], shape);
             const checkSegment = (v1: THREE.Vector3, v2: THREE.Vector3) => {
                 const mid = new THREE.Vector3().addVectors(v1, v2).multiplyScalar(0.5);
                 const distMid = mid.distanceTo(cursorPos);
                 if (distMid < threshold && distMid < minEdgeDist) {
                     bestEdgeSnap = { position: mid, type: 'midpoint', distance: distMid, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distMid;
                     return;
                 }
                 const projected = closestPointOnSegment(cursorPos, v1, v2);
                 const distEdge = projected.distanceTo(cursorPos);
                 if (distEdge < threshold && distEdge < minEdgeDist) {
                     bestEdgeSnap = { position: projected, type: 'edge', distance: distEdge, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distEdge;
                 }
             };
             checkSegment(p1, p2);
             if (hasHeight) {
                 const p1Top = p1.clone().setY(p1.y + currentH);
                 const p2Top = p2.clone().setY(p2.y + currentH);
                 checkSegment(p1Top, p2Top);
                 checkSegment(p1, p1Top);
             }
        }
    }
    if (bestEdgeSnap) return bestEdgeSnap;

    const getShapeUserData = (obj: THREE.Object3D) => {
        if (obj.userData?.isShape) return obj.userData;
        if (obj.parent?.userData?.isShape) return obj.parent.userData;
        return null;
    };
    const shapeData = intersectedObject ? getShapeUserData(intersectedObject.object) : null;
    if (intersectedObject && shapeData) {
         bestSnap = { position: intersectedObject.point, type: 'face', distance: 0, snapObjectId: shapeData.id };
         return bestSnap;
    }

    return bestSnap;
};

// --- Components ---

const SimpleLine: React.FC<{ points: (THREE.Vector3 | [number, number, number])[], color: string, dashed?: boolean, opacity?: number, transparent?: boolean, lineWidth?: number, depthTest?: boolean }> = ({ points, color, dashed, opacity, transparent, lineWidth, depthTest = true }) => {
    const ref = useRef<THREE.Line>(null);
    const geometry = useMemo(() => {
        const pts = points.map(p => (p instanceof THREE.Vector3 ? p : new THREE.Vector3(...p)));
        return new THREE.BufferGeometry().setFromPoints(pts);
    }, [points]);

    useFrame(() => {
        if (dashed && ref.current) {
            ref.current.computeLineDistances();
        }
    });

    return (
        <line ref={ref} geometry={geometry}>
            {dashed ? (
                <lineDashedMaterial color={color} dashSize={0.2} gapSize={0.1} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} />
            ) : (
                <lineBasicMaterial color={color} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} />
            )}
        </line>
    );
};

const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType; snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    return (
        <group position={position}>
            <mesh>
                <sphereGeometry args={[type === 'vertex' ? 0.1 : 0.05]} />
                <meshBasicMaterial color={type === 'midpoint' ? 'cyan' : (type === 'vertex' ? 'magenta' : 'orange')} depthTest={false} />
            </mesh>
            {type === 'edge' && snapEdge && (
                <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="orange" lineWidth={3} depthTest={false} />
            )}
            {type === 'midpoint' && snapEdge && (
                 <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="cyan" lineWidth={3} depthTest={false} />
            )}
        </group>
    );
};

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3; type?: SnapType }> = ({ text, position, type }) => {
    return (
        <Html position={[position.x, position.y + 0.5, position.z]} center style={{ pointerEvents: 'none' }}>
            <div className="bg-slate-900/80 text-white text-xs px-2 py-1 rounded backdrop-blur-sm border border-slate-600 whitespace-nowrap flex items-center gap-1">
                {type && <span className={`w-2 h-2 rounded-full ${type === 'grid' ? 'bg-slate-500' : 'bg-green-500'}`} />}
                {text}
            </div>
        </Html>
    );
};

const ShapeOutline: React.FC<{ shape: IShape; color: string; opacity: number }> = ({ shape, color, opacity }) => {
    const geometry = useMemo(() => {
        const shape2D = createThreeShape(shape.points);
        const geom = new THREE.ExtrudeGeometry(shape2D, { depth: shape.height, bevelEnabled: false });
        return new THREE.EdgesGeometry(geom);
    }, [shape.points, shape.height]);

    return (
        <lineSegments geometry={geometry} rotation={[-Math.PI / 2, 0, 0]}>
            <lineBasicMaterial color={color} transparent opacity={opacity} />
        </lineSegments>
    );
};

// Optimized Shape Renderer
const ShapeRenderer = React.memo(({ shape, isSelected, onSelect, pushPullState, pushPullHandlers, drawingHandlers }: ShapeRendererProps) => {
    const { unit, tool } = useApp();
    const [hovered, setHovered] = useState(false);

    const isPushPullMode = tool === ToolType.PUSH_PULL;
    const highlightColor = isPushPullMode ? shape.color : (isSelected ? HIGHLIGHT_COLOR : shape.color);

    const isTarget = pushPullState.hoveredShapeId === shape.id;
    const isDraggingTop = isTarget && !!pushPullState.dragStartPoint && pushPullState.mode === 'top';

    // Optimization: If dragging Top, use scaleY instead of regenerating geometry
    let scaleY = 1;
    if (isDraggingTop && pushPullState.dragHeight !== undefined && shape.height > 0) {
        scaleY = pushPullState.dragHeight / shape.height;
    }

    const shape2D = useMemo(() => createThreeShape(shape.points), [shape.points]);

    if (shape.type === 'dimension') {
         // Dimension rendering logic (same as before)
         if (shape.points.length < 2) return null;
         const start = new THREE.Vector3(shape.points[0].x, shape.points[0].y, shape.points[0].z);
         const end = new THREE.Vector3(shape.points[1].x, shape.points[1].y, shape.points[1].z);
         const dist = start.distanceTo(end);
         const labelText = unit === 'cm' ? `${(dist * 100).toFixed(1)} cm` : `${dist.toFixed(3)} m`;
         return (
             <group onClick={onSelect} userData={{ isShape: true, id: shape.id }} name="dimension_group">
                <SimpleLine points={[[start.x, start.y+0.05, start.z], [end.x, end.y+0.05, end.z]]} color={isSelected ? HIGHLIGHT_COLOR : shape.color} lineWidth={2} depthTest={false} />
                <mesh position={[start.x, start.y + 0.05, start.z]}><sphereGeometry args={[0.05]} /><meshBasicMaterial color={shape.color} depthTest={false}/></mesh>
                <mesh position={[end.x, end.y + 0.05, end.z]}><sphereGeometry args={[0.05]} /><meshBasicMaterial color={shape.color} depthTest={false}/></mesh>
                <Html position={[(start.x+end.x)/2, (start.y+end.y)/2 + 0.5, (start.z+end.z)/2]} center>
                    <div className="bg-slate-900/90 text-yellow-400 font-mono text-xs px-2 py-1 rounded border border-yellow-500/50 backdrop-blur-sm pointer-events-none whitespace-nowrap shadow-lg">{labelText}</div>
                </Html>
             </group>
         );
    }

    return (
        <group 
            position={[shape.position[0], shape.position[1], shape.position[2]]} 
            rotation={[0, shape.rotation, 0]} 
            scale={[shape.scale[0], shape.scale[1] * scaleY, shape.scale[2]]} 
            userData={{ isShape: true, id: shape.id }} 
            name="shape_group" 
            onClick={!isPushPullMode ? onSelect : undefined}
            onPointerOver={(e) => { 
                e.stopPropagation(); 
                setHovered(true); 
            }}
            onPointerOut={() => { 
                setHovered(false); 
                document.body.style.cursor = 'default'; 
            }}
            onPointerDown={(e) => {
                if (isPushPullMode) pushPullHandlers.handlePointerDown(e);
                else drawingHandlers.handlePointerDown(e);
            }}
            onPointerMove={isPushPullMode ? pushPullHandlers.handlePointerMove : undefined}
            onPointerUp={(e) => {
                pushPullHandlers.handlePointerUp();
                drawingHandlers.handlePointerUp(e);
            }}
        >
            <mesh rotation={[-Math.PI/2, 0, 0]} castShadow receiveShadow userData={{ isShape: true, id: shape.id }}>
                <extrudeGeometry args={[shape2D, { depth: shape.height, bevelEnabled: false }]} />
                <meshStandardMaterial 
                    color={highlightColor} 
                    transparent={shape.type === 'flat'} 
                    opacity={shape.type === 'flat' ? 0.6 : 1.0} 
                    polygonOffset={shape.type === 'flat'} 
                    polygonOffsetFactor={shape.type === 'flat' ? -1 : 0} 
                />
            </mesh>
            <ShapeOutline shape={shape} color="#333" opacity={isPushPullMode ? 0.2 : 0.5} />
        </group>
    );
});

const InteractionLayer: React.FC<{ 
    shapes: IShape[]; 
    setCursorPos: (v: THREE.Vector3) => void;
    setSnapInfo: (s: SnapResult | null) => void;
    cursorPos: THREE.Vector3;
    snapInfo: SnapResult | null;
    drawPoints: IPoint[];
    tool: ToolType;
    onDrawingChange: (points: IPoint[]) => void;
    isDragging: boolean;
    setIsDragging: (b: boolean) => void;
    drawingHeight: number;
    setDrawingHeight: (h: number) => void;
}> = ({ shapes, setCursorPos, setSnapInfo, cursorPos, snapInfo, drawPoints, tool, onDrawingChange, isDragging, setIsDragging, drawingHeight, setDrawingHeight }) => {

    const { scene, camera } = useThree();
    const { formatValue } = useApp();

    useFrame((state) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;

        const raycaster = state.raycaster;
        raycaster.setFromCamera(state.pointer, state.camera);

        let target = new THREE.Vector3();
        let intersectedObj: THREE.Intersection | undefined;

        if (isDragging) {
             const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), -drawingHeight);
             raycaster.ray.intersectPlane(plane, target);
        } else {
            // Optimization: Filter scene children to only interactable objects (Mesh with userData.isShape)
            // Or just use layer 0 if everything else is clean. 
            // Here we stick to intersectObjects but we should ensure we don't hit helper grids too hard.
            // Using a specific array of objects would be better, but scene.children is okay if scene is small.
            // Filter out helpers from results:
            const intersects = raycaster.intersectObjects(scene.children, true);
            intersectedObj = intersects.find(i => {
                const obj = i.object;
                return (obj.userData?.isShape || obj.parent?.userData?.isShape) && i.object.name !== 'helper';
            });

            if (intersectedObj) {
                target.copy(intersectedObj.point);
            } else {
                const groundNormal = new THREE.Vector3(0, 1, 0);
                const plane = new THREE.Plane(groundNormal, 0);
                raycaster.ray.intersectPlane(plane, target);
            }
        }

        if (target) {
            const snap = getGeometrySnap(target, shapes, drawPoints, SNAP_THRESHOLD, intersectedObj);

            // Only update state if significantly changed to reduce renders
            if (snap.position.distanceTo(cursorPos) > 0.001 || snap.type !== snapInfo?.type) {
                setCursorPos(snap.position);
                setSnapInfo(snap);
            }

            if (isDragging) {
                const currentP = { x: snap.position.x, y: drawingHeight, z: snap.position.z };
                 if (tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC || tool === ToolType.MEASURE || tool === ToolType.DRAW_LINE) {
                     if (drawPoints.length > 0) {
                        const newPoints = [drawPoints[0], currentP];
                        onDrawingChange(newPoints);
                     }
                }
            }
        }
    });

    // Render Drawing Visuals
    const activeY = drawPoints.length > 0 ? drawPoints[0].y : cursorPos.y;
    const hoverOffset = 0.02;
    const points = drawPoints.map(p => new THREE.Vector3(p.x, p.y + hoverOffset, p.z));

    let previewShape: React.ReactElement | null = null;
    let infoText = "";

    if (drawPoints.length > 0) {
        const start = points[0];
        const currentEnd = points.length > 1 ? points[points.length - 1] : new THREE.Vector3(cursorPos.x, activeY + hoverOffset, cursorPos.z);

        if (tool === ToolType.DRAW_LINE) {
             const dist = start.distanceTo(currentEnd);
             infoText = `L: ${formatValue(dist)}`;
             previewShape = <SimpleLine points={[start, currentEnd]} color="black" lineWidth={2} />;
        } else if (tool === ToolType.DRAW_POLY) {
            const pointsToRender = [...points, currentEnd];
            if(points.length > 0) {
                 const last = points[points.length - 1];
                 const dist = last.distanceTo(currentEnd);
                 infoText = `L: ${formatValue(dist)}`;
            }
            let closeLoop = false;
            if (points.length > 2) {
                 if (start.distanceTo(currentEnd) < SNAP_THRESHOLD) {
                     infoText = "Close Loop";
                     closeLoop = true;
                 }
            }
            previewShape = (
                <>
                    <SimpleLine points={pointsToRender} color="black" lineWidth={2} />
                    {closeLoop && <mesh position={start}><sphereGeometry args={[0.15]} /><meshBasicMaterial color="#facc15" /></mesh>}
                </>
            );
        } else if (tool === ToolType.MEASURE) {
            const dist = start.distanceTo(currentEnd);
            infoText = `L: ${formatValue(dist)}`;
            previewShape = <SimpleLine points={[start, currentEnd]} color={DIMENSION_COLOR} lineWidth={2} dashed opacity={0.8} />;
        } else if (tool === ToolType.DRAW_RECT) {
             const width = Math.abs(currentEnd.x - start.x);
             const depth = Math.abs(currentEnd.z - start.z);
             infoText = `W: ${formatValue(width)} D: ${formatValue(depth)}`;
             const p1 = start;
             const p2 = new THREE.Vector3(currentEnd.x, start.y, start.z);
             const p3 = currentEnd;
             const p4 = new THREE.Vector3(start.x, start.y, currentEnd.z);
             previewShape = <SimpleLine points={[p1, p2, p3, p4, p1]} color="black" lineWidth={2} />;
        } else if (tool === ToolType.DRAW_CIRCLE) {
             const radius = start.distanceTo(currentEnd);
             infoText = `R: ${formatValue(radius)}`;
             const circlePts = [];
             for(let i=0; i<=32; i++) {
                 const t = (i/32) * Math.PI * 2;
                 circlePts.push(new THREE.Vector3(start.x + Math.cos(t)*radius, start.y, start.z + Math.sin(t)*radius));
             }
             previewShape = <SimpleLine points={circlePts} color="black" lineWidth={2} />;
        } else if (tool === ToolType.DRAW_ARC) {
             const radius = start.distanceTo(currentEnd);
             infoText = `R: ${formatValue(radius)}`;
             previewShape = <SimpleLine points={[start, currentEnd]} color="black" lineWidth={2} dashed />;
        }
    } else {
        if (snapInfo) {
             if (snapInfo.type !== 'grid') infoText = snapInfo.type;
             else infoText = `${formatValue(cursorPos.x)}, ${formatValue(cursorPos.z)}`;
        }
    }

    return (
        <group>
            {points.map((p, i) => (
                <mesh key={i} position={p}>
                    <sphereGeometry args={[0.05]} />
                    <meshBasicMaterial color="red" depthTest={false} />
                </mesh>
            ))}
            {previewShape}
            {snapInfo && <SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} />}
            {(infoText || (snapInfo && snapInfo.type !== 'grid')) && (
                 <CursorTooltip text={infoText || snapInfo!.type} position={cursorPos} type={snapInfo?.type} />
            )}
        </group>
    );
};

// Selection Gizmo - Fix Dragging
const SelectionGizmo: React.FC = () => {
    const { selectedIds, transformMode, updateShape, tool } = useApp();
    const { scene, camera } = useThree();
    const [targetObj, setTargetObj] = useState<THREE.Object3D | null>(null);

    // Enable gizmo if we are in SELECT mode and have exactly one object selected
    const isEnabled = tool === ToolType.SELECT && selectedIds.length === 1;
    const selectedId = isEnabled ? selectedIds[0] : null;

    useFrame(() => {
        if (!isEnabled || !selectedId) {
             if (targetObj) setTargetObj(null);
             return;
        }

        // Check if current target is still valid
        if (targetObj && targetObj.userData?.id === selectedId) return;

        // Traverse to find the object with the matching ID
        // This is robust against hierarchy changes (groups etc.)
        let found: THREE.Object3D | null = null;
        scene.traverse((child) => {
            if (found) return; // Optimization: stop searching if found
            if (child.userData?.isShape && child.userData?.id === selectedId) {
                found = child;
            }
        });

        if (found && found !== targetObj) {
            setTargetObj(found);
        }
    });

    if (!isEnabled || !targetObj) return null;

    return (
        <TransformControls 
            object={targetObj} 
            mode={transformMode} 
            // Important: Disable orbit controls when dragging
            onDraggingChange={(isDragging) => {
                const controls = (camera as any).controls;
                if(controls) controls.enabled = !isDragging;
            }}
            onMouseUp={() => {
                 if (targetObj) {
                     updateShape(selectedId!, {
                         position: [targetObj.position.x, targetObj.position.y, targetObj.position.z],
                         rotation: targetObj.rotation.y,
                         scale: [targetObj.scale.x, targetObj.scale.y, targetObj.scale.z]
                     });
                 }
            }}
        />
    );
};

const CameraHandler: React.FC<{ view: string | null; onFinished: () => void }> = ({ view, onFinished }) => {
    const { camera, controls } = useThree();
    useEffect(() => {
        if (!view) return;
        let targetPos = new THREE.Vector3();
        if (view === '上視圖') targetPos.set(0, 20, 0);
        else if (view === '前視圖') targetPos.set(0, 0, 20);
        else if (view === '右視圖') targetPos.set(20, 0, 0);
        else return;

        camera.position.copy(targetPos);
        camera.lookAt(0, 0, 0);
        if (controls) {
            (controls as any).target.set(0, 0, 0);
            (controls as any).update();
        }
        onFinished();
    }, [view, camera, controls, onFinished]);
    return null;
};

// --- Custom Hooks & Managers ---

const usePushPullManager = () => {
    const { tool, updateShape, shapes } = useApp();
    const { camera, gl } = useThree();

    const [ppState, setPPState] = useState<PushPullState>({
        mode: 'none',
        hoveredShapeId: null,
        hoveredEdgeIndex: -1,
        dragStartPoint: null,
        originalHeight: 0,
        originalPoints: [],
        normal: new THREE.Vector3(0, 1, 0),
        dragHeight: undefined
    });

    // Only for Side Pull (geometry change)
    const [tempShape, setTempShapeState] = useState<IShape | null>(null);
    const tempShapeRef = useRef<IShape | null>(null);
    const setTempShape = (s: IShape | null) => { tempShapeRef.current = s; setTempShapeState(s); };

    const isDragging = !!ppState.dragStartPoint;

    const identifyFace = useCallback((e: ThreeEvent<PointerEvent>): Partial<PushPullState> | null => {
        const object = e.object;
        let curr: THREE.Object3D | null = object;
        let shapeId: string | null = null;
        while(curr) {
            if (curr.userData?.isShape) {
                shapeId = curr.userData.id;
                break;
            }
            curr = curr.parent || null;
        }
        if (!shapeId) return null;

        const shape = shapes.find(s => s.id === shapeId);
        if (!shape || shape.type === 'dimension') return null;

        const intersection = e.intersections[0];
        if (!intersection || !intersection.face) return null;

        const normalMatrix = new THREE.Matrix3().getNormalMatrix(object.matrixWorld);
        const worldNormal = intersection.face.normal.clone().applyMatrix3(normalMatrix).normalize();

        if (worldNormal.y > 0.9) {
            return {
                mode: 'top',
                hoveredShapeId: shapeId,
                hoveredEdgeIndex: -1,
                normal: new THREE.Vector3(0, 1, 0)
            };
        }
        if (Math.abs(worldNormal.y) < 0.2) {
            // ... (Side identification logic logic omitted for brevity, logic remains same)
            // Recalculating local hit for side identification
            const hitPoint = intersection.point.clone().sub(new THREE.Vector3(...shape.position));
            const invRot = -shape.rotation;
            const xLocal = hitPoint.x * Math.cos(invRot) - hitPoint.z * Math.sin(invRot);
            const zLocal = hitPoint.x * Math.sin(invRot) + hitPoint.z * Math.cos(invRot);
            let closestIndex = -1;
            let minDistSq = Infinity;
            const pts = shape.points;
            for(let i=0; i<pts.length; i++) {
                const p1 = pts[i];
                const p2 = pts[(i+1) % pts.length];
                const unscaledX = xLocal / shape.scale[0];
                const unscaledZ = zLocal / shape.scale[2];
                const d2 = distToSegmentSquared(new THREE.Vector3(unscaledX, 0, unscaledZ), new THREE.Vector3(p1.x, 0, p1.z), new THREE.Vector3(p2.x, 0, p2.z));
                if (d2 < minDistSq) { minDistSq = d2; closestIndex = i; }
            }
            if (closestIndex !== -1) {
                const flatNormal = new THREE.Vector3(worldNormal.x, 0, worldNormal.z).normalize();
                return { mode: 'side', hoveredShapeId: shapeId, hoveredEdgeIndex: closestIndex, normal: flatNormal };
            }
        }
        return null;
    }, [shapes]);

    const handlePointerMove = (e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL) return;

        if (isDragging) {
            e.stopPropagation();
            if (!ppState.dragStartPoint || !ppState.hoveredShapeId) return;
            const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
            if (!shape) return;

            const raycaster = new THREE.Raycaster();
            raycaster.setFromCamera(new THREE.Vector2((e.clientX / gl.domElement.clientWidth) * 2 - 1, -(e.clientY / gl.domElement.clientHeight) * 2 + 1), camera);

            if (ppState.mode === 'top') {
                const dragPlane = new THREE.Plane().setFromNormalAndCoplanarPoint(camera.getWorldDirection(new THREE.Vector3()).negate(), ppState.dragStartPoint);
                const target = new THREE.Vector3();
                raycaster.ray.intersectPlane(dragPlane, target);

                if (target) {
                    const deltaY = target.y - ppState.dragStartPoint.y;
                    const newHeight = Math.max(0.01, ppState.originalHeight + deltaY);

                    // Optimization: Do NOT update tempShape (which triggers geometry rebuild). 
                    // Update dragHeight in state, ShapeRenderer will scale visually.
                    setPPState(prev => ({ ...prev, dragHeight: newHeight }));
                }

            } else if (ppState.mode === 'side') {
                // Side pull still requires geometry update, no easy scale optimization for complex polygons
                const dragPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0); 
                const target = new THREE.Vector3();
                raycaster.ray.intersectPlane(dragPlane, target);

                if (target) {
                    const diff = target.clone().sub(ppState.dragStartPoint);
                    const projection = diff.dot(ppState.normal);
                    const moveVectorWorld = ppState.normal.clone().multiplyScalar(projection);
                    const rot = -shape.rotation;
                    const dx = moveVectorWorld.x * Math.cos(rot) - moveVectorWorld.z * Math.sin(rot);
                    const dz = moveVectorWorld.x * Math.sin(rot) + moveVectorWorld.z * Math.cos(rot);
                    const dLocalX = dx / shape.scale[0];
                    const dLocalZ = dz / shape.scale[2];
                    const idx = ppState.hoveredEdgeIndex;
                    const newPoints = ppState.originalPoints.map(p => ({...p}));
                    const p1 = newPoints[idx];
                    const p2 = newPoints[(idx+1) % newPoints.length];
                    p1.x += dLocalX; p1.z += dLocalZ;
                    p2.x += dLocalX; p2.z += dLocalZ;
                    const updatedShape = { ...shape, points: newPoints };
                    setTempShape(updatedShape);
                }
            }

        } else {
            const res = identifyFace(e);
            if (res) {
                e.stopPropagation();
                document.body.style.cursor = res.mode === 'top' ? 'ns-resize' : 'ew-resize';
                setPPState(prev => ({ ...prev, mode: res.mode!, hoveredShapeId: res.hoveredShapeId!, hoveredEdgeIndex: res.hoveredEdgeIndex!, normal: res.normal! }));
            } else {
                setPPState(prev => ({ ...prev, mode: 'none', hoveredShapeId: null }));
                document.body.style.cursor = 'default';
            }
        }
    };

    const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL || e.button !== 0) return; 
        e.stopPropagation();

        if (ppState.mode !== 'none' && ppState.hoveredShapeId) {
             const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
             if(!shape) return;

             const raycaster = new THREE.Raycaster();
             raycaster.setFromCamera(new THREE.Vector2((e.clientX / gl.domElement.clientWidth) * 2 - 1, -(e.clientY / gl.domElement.clientHeight) * 2 + 1), camera);

             let startPoint = new THREE.Vector3();
             if (ppState.mode === 'top') {
                 const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(camera.getWorldDirection(new THREE.Vector3()).negate(), e.point);
                 raycaster.ray.intersectPlane(plane, startPoint);
             } else {
                 const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
                 raycaster.ray.intersectPlane(plane, startPoint);
             }

             setPPState(prev => ({
                 ...prev,
                 dragStartPoint: startPoint,
                 originalHeight: shape.height,
                 dragHeight: shape.height,
                 originalPoints: JSON.parse(JSON.stringify(shape.points))
             }));

             if (ppState.mode === 'side') setTempShape(shape);
        }
    };

    const handlePointerUp = useCallback(() => {
        if (ppState.mode === 'top' && ppState.dragHeight !== undefined && ppState.hoveredShapeId) {
             // Commit height
             updateShape(ppState.hoveredShapeId, { height: ppState.dragHeight });
        } else if (tempShapeRef.current) {
            // Commit points
            updateShape(tempShapeRef.current.id, { points: tempShapeRef.current.points });
        }

        setTempShape(null);
        setPPState(prev => ({ ...prev, dragStartPoint: null, originalPoints: [], dragHeight: undefined }));
    }, [updateShape, ppState.mode, ppState.dragHeight, ppState.hoveredShapeId]);

    useEffect(() => {
        if (isDragging) {
            const onGlobalPointerUp = () => handlePointerUp();
            window.addEventListener('pointerup', onGlobalPointerUp);
            return () => window.removeEventListener('pointerup', onGlobalPointerUp);
        }
    }, [isDragging, handlePointerUp]);

    return { ppState, handlePointerMove, handlePointerDown, handlePointerUp, isDragging, tempShape };
};

const useDrawingManager = () => {
    const { tool, addShape, shapes, wallThickness, setTool, replaceShapes } = useApp();
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [cursorPos, setCursorPos] = useState<THREE.Vector3>(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [isDragging, setIsDragging] = useState(false);
    const [drawingHeight, setDrawingHeight] = useState(0);

    useEffect(() => {
        setDrawPoints([]);
        setSnapInfo(null);
        setIsDragging(false);
        setDrawingHeight(0);
    }, [tool]);

    const finishShape = useCallback((finalPoints: IPoint[]) => {
        let shapeCreated = false;
        const baseHeight = finalPoints.length > 0 ? finalPoints[0].y : 0;

        if (tool === ToolType.DRAW_RECT && finalPoints.length >= 2) {
             const start = finalPoints[0];
             const end = finalPoints[finalPoints.length - 1]; 
             const width = Math.abs(end.x - start.x);
             const depth = Math.abs(end.z - start.z);
             if (width >= 0.01 && depth >= 0.01) {
                 const cx = (start.x + end.x) / 2;
                 const cz = (start.z + end.z) / 2;
                 const points = [{ x: -width/2, y: 0, z: -depth/2 }, { x: width/2, y: 0, z: -depth/2 }, { x: width/2, y: 0, z: depth/2 }, { x: -width/2, y: 0, z: depth/2 }];
                 addShape({ id: `rect-${Date.now()}`, type: 'solid', name: 'Area', points, height: DEFAULT_HEIGHT, color: FLAT_COLOR, position: [cx, baseHeight, cz], rotation: 0, scale: [1, 1, 1] });
                 shapeCreated = true;
             }
        } 
        // ... (Other drawing tools logic - abbreviated for brevity as they are unchanged logic)
        else if (tool === ToolType.DRAW_CIRCLE && finalPoints.length >= 2) {
             const start = finalPoints[0];
             const end = finalPoints[finalPoints.length - 1];
             const radius = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
             if (radius >= 0.01) {
                 addShape({ id: `circle-${Date.now()}`, type: 'solid', name: 'Circle', points: createCirclePoints(radius), height: DEFAULT_HEIGHT, color: FLAT_COLOR, position: [start.x, baseHeight, start.z], rotation: 0, scale: [1, 1, 1] });
                 shapeCreated = true;
             }
        } else if (tool === ToolType.DRAW_ARC && finalPoints.length >= 2) {
             const start = finalPoints[0];
             const end = finalPoints[finalPoints.length - 1];
             const radius = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
             if (radius >= 0.01) {
                 const angle = Math.atan2(end.z - start.z, end.x - start.x);
                 addShape({ id: `arc-${Date.now()}`, type: 'flat', name: 'Door Swing', points: createArcPoints(radius), height: DEFAULT_HEIGHT, color: FLAT_COLOR, position: [start.x, baseHeight, start.z], rotation: -angle, scale: [1, 1, 1] });
                 shapeCreated = true;
             }
        } else if (tool === ToolType.DRAW_LINE && finalPoints.length >= 2) {
             const start = finalPoints[0];
             const end = finalPoints[finalPoints.length - 1]; 
             const dist = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
             if (dist >= 0.01) {
                 let splitOccurred = false;
                 // Split logic
                 for (let i = shapes.length - 1; i >= 0; i--) {
                     const targetShape = shapes[i];
                     if (targetShape.type === 'dimension') continue;
                     const shapeY = targetShape.position[1];
                     const shapeHeight = targetShape.height * targetShape.scale[1];
                     const isVerticallyOverlapping = (baseHeight >= shapeY - 0.02) && (baseHeight <= shapeY + shapeHeight + 0.02);
                     if (!isVerticallyOverlapping) continue;
                     const localStart = inverseTransformPoint(new THREE.Vector3(start.x, 0, start.z), targetShape);
                     const localEnd = inverseTransformPoint(new THREE.Vector3(end.x, 0, end.z), targetShape);
                     const splitResult = splitPolygonByLine(targetShape.points, localStart, localEnd);
                     if (splitResult) {
                         const [polyA, polyB] = splitResult;
                         replaceShapes([targetShape.id], [
                             { ...targetShape, id: `split-${Date.now()}-a`, points: polyA },
                             { ...targetShape, id: `split-${Date.now()}-b`, points: polyB }
                         ]);
                         splitOccurred = true;
                         break;
                     }
                 }
                 if (!splitOccurred) {
                    const angle = Math.atan2(end.z - start.z, end.x - start.x);
                    const thickness = wallThickness || 0.2;
                    const cx = (start.x + end.x) / 2;
                    const cz = (start.z + end.z) / 2;
                    const halfL = dist / 2;
                    const halfW = thickness / 2;
                    const points = [{ x: -halfL, y: 0, z: -halfW }, { x: halfL, y: 0, z: -halfW }, { x: halfL, y: 0, z: halfW }, { x: -halfL, y: 0, z: halfW }];
                    addShape({ id: `wall-${Date.now()}`, type: 'solid', name: 'Wall', points, height: DEFAULT_HEIGHT, color: DEFAULT_COLOR, position: [cx, baseHeight, cz], rotation: -angle, scale: [1, 1, 1] });
                 }
                 shapeCreated = true;
             }
        } else if (tool === ToolType.DRAW_POLY && finalPoints.length >= 3) {
             const cx = finalPoints.reduce((s, pt) => s + pt.x, 0) / finalPoints.length;
             const cz = finalPoints.reduce((s, pt) => s + pt.z, 0) / finalPoints.length;
             const localPoints = finalPoints.map(pt => ({ x: pt.x - cx, y: 0, z: pt.z - cz }));
             addShape({ id: `poly-${Date.now()}`, type: 'solid', name: 'Polygon', points: localPoints, height: DEFAULT_HEIGHT, color: DEFAULT_COLOR, position: [cx, baseHeight, cz], rotation: 0, scale: [1, 1, 1] });
             shapeCreated = true;
        } else if (tool === ToolType.MEASURE && finalPoints.length >= 2) {
             const start = finalPoints[0];
             const end = finalPoints[finalPoints.length - 1];
             addShape({ id: `dim-${Date.now()}`, type: 'dimension', name: 'Dimension', points: [start, end], height: 0, color: DIMENSION_COLOR, position: [0, 0, 0], rotation: 0, scale: [1, 1, 1] });
             shapeCreated = true;
        }
        setDrawPoints([]);
        if (shapeCreated) setTool(ToolType.SELECT);
    }, [tool, addShape, wallThickness, setTool, shapes, replaceShapes]);

    const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;
        if (e.button === 0) {
            e.stopPropagation();
            if (!isDragging && drawPoints.length === 0) setDrawingHeight(cursorPos.y);

            const p = { x: cursorPos.x, y: cursorPos.y, z: cursorPos.z };
            if (tool === ToolType.DRAW_POLY) {
                 if (drawPoints.length > 2) {
                     const first = drawPoints[0];
                     const dist = Math.sqrt((p.x - first.x)**2 + (p.z - first.z)**2);
                     if (dist < SNAP_THRESHOLD) { finishShape(drawPoints); return; }
                 }
                 setDrawPoints(prev => [...prev, p]);
            } else {
                setDrawPoints([p]);
                setIsDragging(true);
            }
        }
    };

    const handlePointerUp = (e: ThreeEvent<PointerEvent>) => {
         if (isDragging && e.button === 0) {
             e.stopPropagation();
             setIsDragging(false);
             if (tool !== ToolType.DRAW_POLY) {
                 if (drawPoints.length > 1) {
                     const start = drawPoints[0];
                     const end = drawPoints[drawPoints.length - 1];
                     const dist = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
                     if (dist > 0.01) finishShape(drawPoints);
                     else setDrawPoints([]);
                 }
             }
         }
    };

    const handleClick = (e: ThreeEvent<MouseEvent>) => {};

    return { 
        handleClick, handlePointerDown, handlePointerUp, 
        drawPoints, setDrawPoints, // Exposed for InteractionLayer to update
        cursorPos, setCursorPos, 
        snapInfo, setSnapInfo,
        tool, 
        isDragging, setIsDragging,
        drawingHeight, setDrawingHeight
    };
};

const SideFaceHighlight: React.FC<{ shape: IShape, edgeIndex: number, height: number }> = React.memo(({ shape, edgeIndex, height }) => {
    const pts = shape.points;
    const p1 = pts[edgeIndex];
    const p2 = pts[(edgeIndex + 1) % pts.length];

    const geometry = useMemo(() => {
        const geom = new THREE.BufferGeometry();
        // Construct quad in local space (x, z) with y extrusion
        const vertices = new Float32Array([
            p1.x, 0, p1.z,
            p2.x, 0, p2.z,
            p2.x, height, p2.z,

            p2.x, height, p2.z,
            p1.x, height, p1.z,
            p1.x, 0, p1.z
        ]);

        geom.setAttribute('position', new THREE.BufferAttribute(vertices, 3));
        geom.computeVertexNormals();
        return geom;
    }, [p1, p2, height]);

    return (
        <mesh geometry={geometry}>
             <meshBasicMaterial color="#fbbf24" transparent opacity={0.4} side={THREE.DoubleSide} depthTest={false} />
             <lineSegments>
                <edgesGeometry args={[geometry]} />
                <lineBasicMaterial color="#fbbf24" />
             </lineSegments>
        </mesh>
    );
});

const FaceHighlighter: React.FC<{ ppState: PushPullState; shapes: IShape[]; tempShape: IShape | null }> = ({ ppState, shapes, tempShape }) => {
    const { tool } = useApp();
    if (tool !== ToolType.PUSH_PULL || ppState.mode === 'none' || !ppState.hoveredShapeId) return null;

    const shape = (tempShape && tempShape.id === ppState.hoveredShapeId) ? tempShape : shapes.find(s => s.id === ppState.hoveredShapeId);
    if (!shape) return null;

    const shape2D = useMemo(() => createThreeShape(shape.points), [shape.points]);
    const height = (ppState.dragHeight !== undefined) ? ppState.dragHeight : shape.height;

    return (
        <group 
            position={[shape.position[0], shape.position[1], shape.position[2]]} 
            rotation={[0, shape.rotation, 0]} 
            scale={[shape.scale[0], 1, shape.scale[2]]}
        >
            {ppState.mode === 'top' && (
                <mesh rotation={[-Math.PI/2, 0, 0]} position={[0, height, 0]}>
                    <shapeGeometry args={[shape2D]} />
                    <meshBasicMaterial color="#fbbf24" transparent opacity={0.4} side={THREE.DoubleSide} depthTest={false} />
                </mesh>
            )}

            {ppState.mode === 'side' && ppState.hoveredEdgeIndex !== -1 && (
                <SideFaceHighlight shape={shape} edgeIndex={ppState.hoveredEdgeIndex} height={height} />
            )}
        </group>
    );
};

const VertexHandle: React.FC<{ index: number, point: IPoint, shape: IShape, updateShape: (id: string, updates: Partial<IShape>) => void }> = ({ index, point, shape, updateShape }) => {
    const [dragging, setDragging] = useState(false);
    const { gl } = useThree();
    const ref = useRef<THREE.Mesh>(null);
    const [hovered, setHovered] = useState(false);

    const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
        e.stopPropagation();
        setDragging(true);
        (gl.domElement as HTMLElement).setPointerCapture(e.pointerId);
    };

    const handlePointerUp = (e: ThreeEvent<PointerEvent>) => {
        e.stopPropagation();
        setDragging(false);
        (gl.domElement as HTMLElement).releasePointerCapture(e.pointerId);
    };

    const handlePointerMove = (e: ThreeEvent<PointerEvent>) => {
        if (!dragging) return;
        e.stopPropagation();

        if (ref.current && ref.current.parent) {
            const worldPoint = e.point.clone();
            const localPoint = ref.current.parent.worldToLocal(worldPoint);

            const newPoints = [...shape.points];
            newPoints[index] = { x: localPoint.x, y: 0, z: localPoint.z };
            updateShape(shape.id, { points: newPoints });
        }
    };

    return (
        <mesh 
            ref={ref}
            position={[point.x, 0, point.z]} 
            onPointerDown={handlePointerDown}
            onPointerUp={handlePointerUp}
            onPointerMove={handlePointerMove}
            onPointerOver={() => setHovered(true)}
            onPointerOut={() => setHovered(false)}
        >
            <sphereGeometry args={[0.15]} />
            <meshBasicMaterial color={dragging ? "#fbbf24" : (hovered ? "#38bdf8" : "white")} depthTest={false} />
        </mesh>
    );
};

const VertexEditor: React.FC = () => {
    const { selectedIds, shapes, updateShape, tool } = useApp();
    if (selectedIds.length !== 1 || tool !== ToolType.SELECT) return null;

    const shape = shapes.find(s => s.id === selectedIds[0]);
    if (!shape || (shape.type !== 'solid' && shape.type !== 'flat')) return null;

    return (
        <group 
            position={[shape.position[0], shape.position[1], shape.position[2]]} 
            rotation={[0, shape.rotation, 0]} 
            scale={[shape.scale[0], shape.scale[1], shape.scale[2]]}
        >
            {shape.points.map((pt, i) => (
                <VertexHandle key={i} index={i} point={pt} shape={shape} updateShape={updateShape} />
            ))}
        </group>
    );
};

// --- Scene Content ---

const SceneContent: React.FC<{ view: string | null; onViewFinished: () => void }> = ({ view, onViewFinished }) => {
    const { shapes, selectedIds, selectShape, tool } = useApp();

    // Separate Hooks
    const pushPullManager = usePushPullManager();
    const { tempShape } = pushPullManager;

    // Use Drawing Logic Hook (State is local to this component, but passed down)
    const dm = useDrawingManager();

    const handleShapeClick = useCallback((e: ThreeEvent<MouseEvent>, id: string) => {
        if (tool === ToolType.SELECT) {
            e.stopPropagation();
            selectShape(id, e.shiftKey);
        } else if (tool !== ToolType.PUSH_PULL) {
             dm.handleClick(e);
        }
    }, [tool, selectShape, dm.handleClick]);

    const isDrawingTool = [ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DRAW_POLY, ToolType.DRAW_LINE, ToolType.DRAW_ARC, ToolType.MEASURE].includes(tool);

    return (
        <>
            <ambientLight intensity={0.5} />
            <directionalLight position={[10, 20, 10]} intensity={1} castShadow shadow-mapSize={[2048, 2048]}>
                <orthographicCamera attach="shadow-camera" args={[-20, 20, 20, -20]} />
            </directionalLight>
            <Grid infiniteGrid sectionSize={1} cellSize={0.5} sectionColor="#cbd5e1" cellColor="#e2e8f0" fadeDistance={50} position={[0, -0.005, 0]} />

            {/* Invisible Ground Plane for Events */}
            <mesh 
                rotation={[-Math.PI / 2, 0, 0]} 
                position={[0, -0.01, 0]} 
                onClick={tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL ? dm.handleClick : undefined}
                onPointerDown={dm.handlePointerDown}
                onPointerUp={(e) => {
                    dm.handlePointerUp(e);
                    pushPullManager.handlePointerUp(); 
                }}
                onPointerMove={tool === ToolType.PUSH_PULL ? pushPullManager.handlePointerMove : undefined}
            >
                <planeGeometry args={[200, 200]} />
                <meshBasicMaterial transparent opacity={0} depthWrite={false} />
            </mesh>

            <group>
                {shapes.map(shape => {
                    const shapeToRender = (tempShape && tempShape.id === shape.id) ? tempShape : shape;
                    return (
                        <ShapeRenderer 
                            key={shape.id} 
                            shape={shapeToRender} 
                            isSelected={selectedIds.includes(shape.id)} 
                            onSelect={(e) => handleShapeClick(e, shape.id)} 
                            pushPullState={pushPullManager.ppState}
                            pushPullHandlers={{
                                handlePointerDown: pushPullManager.handlePointerDown,
                                handlePointerUp: pushPullManager.handlePointerUp,
                                handlePointerMove: pushPullManager.handlePointerMove
                            }}
                            drawingHandlers={{
                                handlePointerDown: dm.handlePointerDown,
                                handlePointerUp: dm.handlePointerUp,
                                handleClick: dm.handleClick
                            }}
                        />
                    );
                })}
            </group>

            <InteractionLayer 
                shapes={shapes}
                tool={tool}
                setCursorPos={dm.setCursorPos}
                setSnapInfo={dm.setSnapInfo}
                cursorPos={dm.cursorPos}
                snapInfo={dm.snapInfo}
                drawPoints={dm.drawPoints}
                onDrawingChange={dm.setDrawPoints}
                isDragging={dm.isDragging}
                setIsDragging={dm.setIsDragging}
                drawingHeight={dm.drawingHeight}
                setDrawingHeight={dm.setDrawingHeight}
            />

            <FaceHighlighter ppState={pushPullManager.ppState} shapes={shapes} tempShape={tempShape} />
            <SelectionGizmo />
            <VertexEditor />

            <OrbitControls 
                makeDefault 
                minPolarAngle={0} 
                maxPolarAngle={Math.PI / 2.1} 
                enableDamping={false}
                enabled={!pushPullManager.isDragging && !dm.isDragging}
                mouseButtons={{
                    LEFT: THREE.MOUSE.ROTATE,
                    MIDDLE: THREE.MOUSE.PAN,
                    RIGHT: isDrawingTool ? undefined : THREE.MOUSE.PAN
                }}
            />
            <CameraHandler view={view} onFinished={onViewFinished} />
            <GizmoHelper alignment="bottom-right" margin={[80, 80]}>
                <GizmoViewport axisColors={['#ef4444', '#22c55e', '#3b82f6']} labelColor="black" />
            </GizmoHelper>
        </>
    );
};

const Viewport: React.FC = () => {
    const [view, setView] = useState<string | null>(null);

    return (
        <div className="w-full h-full bg-slate-900 relative" onContextMenu={(e) => e.preventDefault()}>
            <div className="absolute top-4 left-1/2 -translate-x-1/2 z-10 flex gap-2 bg-slate-800/90 p-1 rounded-lg border border-slate-700 backdrop-blur-sm">
                {['上視圖', '前視圖', '右視圖', '透視'].map(v => (
                    <button key={v} onClick={() => setView(v === '透視' ? null : v)} className={`text-xs px-3 py-1.5 rounded transition-colors ${view === v || (v === '透視' && !view) ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white hover:bg-slate-700'}`}>{v}</button>
                ))}
            </div>
            <Canvas shadows camera={{ position: [5, 8, 8], fov: 45 }}>
